interface DomainKnowledgeRoute {
  groupId?: string;
  categoryId?: string;
  tab?: KnowledgeKind;
  companyId?: string;
  sectionKind?: KnowledgeKind;
  cardTitle?: string;
  lessonTitle?: string;
}

// dkPractice / dkChapter belong to the open lesson's practice link, so any route change drops them.
const DOMAIN_ROUTE_KEYS = ['dkGroup', 'dkIndustry', 'dkTab', 'dkCompany', 'dkSection', 'dkModule', 'dkLesson', 'dkPractice', 'dkChapter'] as const;

function readDomainKnowledgeRoute(): DomainKnowledgeRoute {
  if (typeof window === 'undefined') return {};
  const params = new URLSearchParams(window.location.search);
  const tab = params.get('dkTab');
  const sectionKind = params.get('dkSection');
  return {
    groupId: params.get('dkGroup') ?? undefined,
    categoryId: params.get('dkIndustry') ?? undefined,
    tab: tab === 'Company' ? 'Company' : tab === 'Industry' ? 'Industry' : undefined,
    companyId: params.get('dkCompany') ?? undefined,
    sectionKind: sectionKind === 'Company' ? 'Company' : sectionKind === 'Industry' ? 'Industry' : undefined,
    cardTitle: params.get('dkModule') ?? undefined,
    lessonTitle: params.get('dkLesson') ?? undefined,
  };
}

function writeDomainKnowledgeRoute(route: DomainKnowledgeRoute, replace = false) {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  DOMAIN_ROUTE_KEYS.forEach((key) => url.searchParams.delete(key));
  if (route.groupId) url.searchParams.set('dkGroup', route.groupId);
  if (route.categoryId) url.searchParams.set('dkIndustry', route.categoryId);
  if (route.tab) url.searchParams.set('dkTab', route.tab);
  if (route.companyId) url.searchParams.set('dkCompany', route.companyId);
  if (route.sectionKind) url.searchParams.set('dkSection', route.sectionKind);
  if (route.cardTitle) url.searchParams.set('dkModule', route.cardTitle);
  if (route.lessonTitle) url.searchParams.set('dkLesson', route.lessonTitle);
  window.history[replace ? 'replaceState' : 'pushState']({}, '', url);
}

