// Implementation status is derived from the lesson decks the frontend actually ships, so research-only
// modules and lessons can never be presented as available learning content.
const COMMERCIAL_BANKING_DECK_REGISTRY: Record<string, Record<string, unknown>> = {
  'How the Industry Works': COMMERCIAL_BANKING_MODULE01_DECKS,
  'How Value Moves Through the Industry': COMMERCIAL_BANKING_MODULE02_DECKS,
  'How Companies Make Money': COMMERCIAL_BANKING_MODULE03_DECKS,
  'Who Competes—and Why They Win': COMMERCIAL_BANKING_MODULE04_DECKS,
  'What Is Changing Next': COMMERCIAL_BANKING_MODULE05_DECKS,
};

function isCommercialBankingModuleInDevelopment(industryId?: string, moduleTitle?: string) {
  return industryId === 'banking-commercial' && !COMMERCIAL_BANKING_DECK_REGISTRY[moduleTitle ?? ''];
}

function isCommercialBankingLessonInDevelopment(industryId?: string, moduleTitle?: string, lessonTitle?: string) {
  if (industryId !== 'banking-commercial') return false;
  return !COMMERCIAL_BANKING_DECK_REGISTRY[moduleTitle ?? '']?.[lessonTitle ?? ''];
}

function isCommercialBankingLessonUnderReview(industryId?: string, moduleTitle?: string, lessonTitle?: string) {
  return industryId === 'banking-commercial'
    && moduleTitle === 'What Is Changing Next'
    && Boolean(lessonTitle?.startsWith('5.4'))
    && (String(COMMERCIAL_BANKING_MODULE05_LEGAL_STATUS) !== 'Ready for Review' || isLessonHeldForReview('COMMERCIAL_BANKING_MODULE05', lessonTitle ?? ''));
}

