function resolveCommercialBankingLessonPresentation(lesson: KnowledgeCard): ResolvedLessonPresentation {
  const code = lesson.title.match(COMMERCIAL_BANKING_LESSON_CODE)?.[1];
  const definition = code ? COMMERCIAL_BANKING_LESSON_PRESENTATION[code] : undefined;
  const vietnamese = cbViLessonCopy(lesson.title);
  return {
    title: vietnamese?.title ?? lesson.title.replace(COMMERCIAL_BANKING_LESSON_CODE, ''),
    subtitle: vietnamese?.subtitle ?? definition?.subtitle ?? 'Commercial Banking',
    description: vietnamese?.description ?? definition?.description ?? lesson.description,
    icon: definition?.icon ?? BookOpen,
  };
}

