function resolveLessonPresentation(
  lesson: KnowledgeCard,
  index: number,
  industryName: string,
  industryId?: string,
): ResolvedLessonPresentation {
  if (industryId === 'banking-commercial') return resolveCommercialBankingLessonPresentation(lesson);
  const retailPresentation = resolveRetailLessonPresentation(industryId, (lesson as KnowledgeCard & { sectorTitle?: string }).sectorTitle ?? lesson.title);
  if (retailPresentation) return retailPresentation;
  const definition = INDUSTRY_CONTEXT_LESSON_PRESENTATION[lesson.title]
    ?? VALUE_CHAIN_LESSON_PRESENTATION[lesson.title]
    ?? BUSINESS_MODELS_LESSON_PRESENTATION[lesson.title]
    ?? COMPETITIVE_LANDSCAPE_LESSON_PRESENTATION[lesson.title]
    ?? TRENDS_OUTLOOK_LESSON_PRESENTATION[lesson.title];
  if (definition) {
    return {
      title: (industryId === 'fmcg-beverages-alc' ? BEER_LESSON_TITLES[lesson.title] : undefined) ?? definition.title,
      subtitle: definition.subtitle,
      description: definition.description(industryName),
      icon: definition.icon,
    };
  }

  return {
    title: lesson.title,
    subtitle: `Lesson ${String(index + 1).padStart(2, '0')}`,
    description: lesson.description,
    icon: BookOpen,
  };
}

