interface LessonReaderArchive {
  notes: Record<number, string>;
  completed: number[];
  positions: Record<number, number>;
}

interface LessonReaderState {
  notes: Record<number, string>;
  completed: number[];
  positions: Record<number, number>;
  migrations: string[];
  /** Recoverable copy of the pre-restructure learner state; never rendered as new completion. */
  legacyArchive?: LessonReaderArchive;
  view?: ReaderView;
  /** "Mark complete" chapters captured once when chapter checks were introduced; preserved as historical completion. */
  legacyCompletedChapters?: number[];
}

const EMPTY_READER_STATE: LessonReaderState = { notes: {}, completed: [], positions: {}, migrations: [] };

function loadLessonReaderState(storageKey: string): LessonReaderState {
  try {
    const saved = localStorage.getItem(storageKey);
    if (!saved) return EMPTY_READER_STATE;
    const parsed = JSON.parse(saved) as Partial<LessonReaderState>;
    return {
      ...parsed,
      notes: parsed.notes ?? {},
      completed: Array.isArray(parsed.completed) ? parsed.completed : [],
      positions: parsed.positions ?? {},
      migrations: Array.isArray(parsed.migrations) ? parsed.migrations : [],
      legacyArchive: parsed.legacyArchive,
    };
  } catch {
    return EMPTY_READER_STATE;
  }
}

function saveLessonReaderState(storageKey: string, state: LessonReaderState) {
  try {
    localStorage.setItem(storageKey, JSON.stringify(state));
  } catch {
    // Keep the reader usable when browser storage is unavailable.
  }
}

const CHAPTER_NUMBER_PREFIX = /^\d{2}\s+(?=\S)/;
const displayChapterTitle = (title?: string) => (title ?? '').replace(CHAPTER_NUMBER_PREFIX, '');

function extractNodeText(node: ReactNode): string {
  if (typeof node === 'string' || typeof node === 'number') return String(node);
  if (Array.isArray(node)) return node.map(extractNodeText).join(' ');
  if (node && typeof node === 'object' && 'props' in node) {
    return extractNodeText((node as { props?: { children?: ReactNode } }).props?.children);
  }
  return '';
}

function estimateReadingMinutes(card: FlashcardData): number {
  const concepts = card.concepts.flatMap((concept) => [concept.title, concept.technicalLabel, concept.summary, concept.whyItMatters, concept.industryDetail, concept.points?.join(' '), concept.extra, concept.groupLabel]);
  const text = [
    card.objective, card.keyInsight, card.mateIntro, card.visualIntro, card.statsNote, card.chapterRecap,
    card.deepDiveTitle, card.chapterWhy, card.objectives?.join(' '), card.recap.join(' '),
    card.narrative?.flatMap((item) => [item.label, item.text]).join(' '),
    card.keyTerms.flatMap((item) => [item.term, item.definition]).join(' '),
    card.statTiles?.flatMap((item) => [item.value, item.label, item.subtitle, item.description]).join(' '),
    card.stats?.flatMap((item) => [item.value, item.label]).join(' '), concepts.join(' '), extractNodeText(card.body),
  ].filter(Boolean).join(' ');
  const words = text.trim() ? text.trim().split(/\s+/) : [];
  // Vietnamese separates every syllable with a space, so the same content has about 1.5x the tokens of English.
  const vietnamese = words.length > 0 && words.filter((word) => /[ăâđêôơưạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹ]/i.test(word)).length >= words.length * 0.2;
  return Math.max(3, Math.ceil(words.length / (vietnamese ? 270 : 180)));
}

function migrateLessonReaderState(state: LessonReaderState, cards: FlashcardData[], migrationId: string): LessonReaderState {
  if (state.migrations.includes(migrationId)) return state;
  const mappedCards = cards.map((card, index) => ({ card, index })).filter(({ card }) => Number.isInteger(card.legacyIndex) || Boolean(card.legacyIndexes?.length));
  if (!mappedCards.length) return state;
  const notes: Record<number, string> = {};
  const positions: Record<number, number> = {};
  const completed: number[] = [];
  const legacyArchive: LessonReaderArchive = state.legacyArchive ?? {
    notes: { ...state.notes },
    positions: { ...state.positions },
    completed: [...state.completed],
  };
  mappedCards.forEach(({ card, index }) => {
    const legacyIndexes = card.legacyIndexes?.length ? card.legacyIndexes : [card.legacyIndex as number];
    const noteEntries = legacyIndexes
      .filter((legacyIndex) => Object.prototype.hasOwnProperty.call(state.notes, legacyIndex) && state.notes[legacyIndex])
      .map((legacyIndex) => ({ legacyIndex, note: state.notes[legacyIndex] }));
    if (noteEntries.length === 1) notes[index] = noteEntries[0].note;
    if (noteEntries.length > 1) notes[index] = noteEntries.map(({ legacyIndex, note }) => `[Former Chapter ${legacyIndex + 1}]\n${note}`).join('\n\n');
    const completionIndex = Number.isInteger(card.legacyCompletionIndex) ? card.legacyCompletionIndex as number : card.legacyIndex as number;
    const savedPositions = legacyIndexes.filter((legacyIndex) => Object.prototype.hasOwnProperty.call(state.positions, legacyIndex)).map((legacyIndex) => state.positions[legacyIndex]);
    if (Object.prototype.hasOwnProperty.call(state.positions, completionIndex)) positions[index] = state.positions[completionIndex];
    else if (savedPositions.length) positions[index] = Math.max(...savedPositions);
    if (Number.isInteger(completionIndex) && state.completed.includes(completionIndex)) completed.push(index);
  });
  return { notes, positions, completed, migrations: [...state.migrations, migrationId], legacyArchive };
}

