type DairyVCVisualKind = keyof typeof DAIRY_VC_VISUALS;

function renderDairyVCVisual(kind: string): ReactNode {
  const render = (DAIRY_VC_VISUALS as Record<string, () => ReactNode>)[kind];
  return render ? render() : null;
}

function CtxBadge({ children, primary }: { children: ReactNode; primary?: boolean }) {
  return (
    <span className={primary ? 'inline-flex rounded-full bg-red-600 px-2.5 py-1 text-[11px] font-bold text-white' : 'inline-flex rounded-full bg-red-50 px-2.5 py-1 text-[11px] font-bold text-red-600 ring-1 ring-red-100'}>{children}</span>
  );
}

function DairyCtx2aTimelineVisual() {
  const milestones: { year: string; label: string; detail: string; icon: LucideIcon; primary?: boolean }[] = [
    { year: '1860s', label: 'Pasteurization', detail: 'Louis Pasteur established the scientific foundations for heat treatment that reduces harmful microorganisms.', icon: ThermometerSun },
    { year: '1961', label: 'Aseptic packaging', detail: 'Tetra Pak launched its aseptic packaging system, supporting shelf-stable liquid foods.', icon: Building2 },
    { year: 'UHT era', label: 'UHT processing', detail: 'With aseptic packaging, unopened milk can be stored without refrigeration under specified conditions.', icon: Cpu, primary: true },
  ];
  const phases: { icon: LucideIcon; label: string; detail: string }[] = [
    { icon: Sprout, label: 'Traditional farming', detail: 'Small-scale, local, seasonal' },
    { icon: Building2, label: 'Industrialization', detail: 'Mechanized milking, refrigeration, central processing' },
    { icon: Truck, label: 'Integrated supply chains', detail: 'Farms to retailers, linked end to end' },
  ];
  return (
    <VCFrame
      title="Three Waves That Built the Modern Dairy Industry"
      subtitle="Three technology milestones sit at the heart of the shift from local farms to global supply chains."
      takeaway="Preservation, processing, and packaging breakthroughs made dairy safer, more accessible, and distributable worldwide."
    >
      <div>
        <VCLabel>Technology milestones</VCLabel>
        <ol className="mt-3 space-y-3 border-l-2 border-red-100 pl-5">
          {milestones.map(({ year, label, detail, icon: Icon, primary }) => (
            <li key={label} className="relative">
              <span className={`absolute -left-[31px] top-4 h-3 w-3 rounded-full border-2 border-white ${primary ? 'bg-red-600' : 'bg-red-300'}`} aria-hidden />
              <div className={`flex items-start gap-3 rounded-2xl border bg-white p-3 ${primary ? 'border-red-300' : 'border-slate-200'}`}>
                <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-red-50 text-red-600"><Icon className="h-5 w-5" /></span>
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <CtxBadge primary={primary}>{year}</CtxBadge>
                    <p className="text-sm font-black text-slate-900">{label}</p>
                  </div>
                  <p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p>
                </div>
              </div>
            </li>
          ))}
        </ol>
      </div>
      <div>
        <VCLabel>How the industry itself evolved</VCLabel>
        <div className="mt-2">
          <div className="flex flex-col items-stretch gap-2 sm:flex-row">
            {phases.flatMap(({ icon: Icon, label, detail }, index) => {
              const card = (
                <div key={label} className={`flex-1 rounded-xl border p-3 text-center ${index === phases.length - 1 ? 'border-2 border-red-500 bg-white shadow-sm' : 'border-slate-200 bg-slate-50'}`}>
                  <Icon className="mx-auto h-5 w-5 text-red-600" />
                  <p className="mt-1 text-xs font-black text-slate-900">{label}</p>
                  <p className="mt-1 text-[11px] leading-4 text-slate-500">{detail}</p>
                </div>
              );
              return index < phases.length - 1
                ? [card, <div key={`${label}-arrow`} className="flex items-center justify-center"><ArrowRight className="h-4 w-4 rotate-90 text-red-400 sm:rotate-0" /></div>]
                : [card];
            })}
          </div>
        </div>
      </div>
      <VCNote label="Reading the dates:">They mark scientific and commercial developments, not the first use of each technology worldwide.</VCNote>
    </VCFrame>
  );
}

