function LearningVisualViewer({
  src,
  alt,
  onClose,
  children,
}: {
  src?: string;
  alt: string;
  onClose: () => void;
  children?: ReactNode;
}) {
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const dragRef = useRef<{ pointerId: number; x: number; y: number; panX: number; panY: number } | null>(null);

  const updateZoom = (nextZoom: number) => {
    const clamped = Math.max(1, Math.min(4, nextZoom));
    setZoom(clamped);
    if (clamped === 1) setPan({ x: 0, y: 0 });
  };

  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
      if (event.key === '+' || event.key === '=') updateZoom(zoom + 0.5);
      if (event.key === '-') updateZoom(zoom - 0.5);
      if (event.key === '0') updateZoom(1);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onClose, zoom]);

  return (
    <div
      className="fixed inset-0 z-[100] flex flex-col bg-slate-950/90 p-3 sm:p-5"
      role="dialog"
      aria-modal="true"
      aria-label="Expanded learning visual"
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div className="mb-3 flex items-center justify-end gap-2">
        <button type="button" onClick={() => updateZoom(zoom - 0.5)} disabled={zoom <= 1} className="flex h-10 min-w-10 items-center justify-center rounded-xl bg-white px-3 text-sm font-bold text-slate-700 shadow-sm disabled:opacity-40" aria-label="Zoom out">−</button>
        <span className="min-w-16 rounded-xl bg-white px-3 py-2.5 text-center text-xs font-bold tabular-nums text-slate-600">{Math.round(zoom * 100)}%</span>
        <button type="button" onClick={() => updateZoom(zoom + 0.5)} disabled={zoom >= 4} className="flex h-10 min-w-10 items-center justify-center rounded-xl bg-white px-3 text-sm font-bold text-slate-700 shadow-sm disabled:opacity-40" aria-label="Zoom in">+</button>
        <button type="button" onClick={() => updateZoom(1)} className="hidden h-10 items-center justify-center rounded-xl bg-white px-3 text-xs font-bold text-slate-700 shadow-sm sm:flex">Reset</button>
        <button type="button" onClick={onClose} autoFocus className="ml-1 flex h-10 w-10 items-center justify-center rounded-xl bg-white text-slate-700 shadow-sm" aria-label="Close image viewer"><X className="h-5 w-5" /></button>
      </div>

      <div
        className={`flex min-h-0 flex-1 items-center justify-center rounded-xl ${zoom > 1 ? 'cursor-grab overflow-hidden active:cursor-grabbing' : 'cursor-zoom-in overflow-auto'}`}
        style={{ touchAction: zoom > 1 ? 'none' : 'pan-y' }}
        onDoubleClick={() => updateZoom(zoom > 1 ? 1 : 2)}
        onWheel={(event) => {
          event.preventDefault();
          updateZoom(zoom + (event.deltaY < 0 ? 0.25 : -0.25));
        }}
        onPointerDown={(event) => {
          if (zoom <= 1) return;
          dragRef.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, panX: pan.x, panY: pan.y };
          event.currentTarget.setPointerCapture(event.pointerId);
        }}
        onPointerMove={(event) => {
          const drag = dragRef.current;
          if (!drag || drag.pointerId !== event.pointerId) return;
          setPan({ x: drag.panX + event.clientX - drag.x, y: drag.panY + event.clientY - drag.y });
        }}
        onPointerUp={(event) => {
          if (dragRef.current?.pointerId === event.pointerId) dragRef.current = null;
          if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
        }}
        onPointerCancel={() => { dragRef.current = null; }}
      >
        <div
          className={`origin-center transition-transform duration-150 motion-reduce:transition-none ${children ? 'my-auto w-full max-w-6xl' : 'flex max-h-full max-w-full items-center justify-center'}`}
          style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})` }}
        >
          {children ?? (
            <img
              src={src}
              alt={alt}
              draggable={false}
              className="block max-h-full max-w-full select-none object-contain"
            />
          )}
        </div>
      </div>
      <p className="mt-2 text-center text-[11px] text-white/70">Use +/− or your mouse wheel to zoom. Drag to pan when zoomed.</p>
    </div>
  );
}

