const AVAILABLE_CATEGORY_IDS = ['fmcg-dairy', 'fmcg-packaged-food', 'fmcg-beverages-na', 'fmcg-beverages-alc', 'banking-commercial', ...RETAIL_SECTOR_IDS];

function isPackagedFoodLessonUnderReview(industryId?: string, moduleTitle?: string, lessonTitle?: string) {
  return industryId === 'fmcg-packaged-food'
    && moduleTitle === 'What Is Changing Next'
    && lessonTitle === 'Regulatory & Sustainability Trends';
}

function NabDef1EcosystemVisual() {
  return (
    <VCFrame
      title="The Non-Alcoholic Beverage Ecosystem"
      subtitle="How a drink travels from raw inputs to the person who finally drinks it."
      takeaway="The industry is a connected system: suppliers, producers, distributors and retailers all sit between the brand and the consumer."
    >
      <VCFlow
        nodes={[
          { label: 'Input suppliers', detail: 'Water, sugar, flavours, CO2, packaging' },
          { label: 'Producers & bottlers', detail: 'Formulate, bottle, quality-check', primary: true },
          { label: 'Distribution & retail', detail: 'Distributors, GT, MT, e-commerce' },
          { label: 'Consumers', detail: 'At home, on the go, on-trade' },
        ]}
      />
      <div>
        <VCLabel>Who takes part</VCLabel>
        <div className="mt-2 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          <VCTile icon={Sprout} label="Input suppliers" detail="Ingredient, water and packaging makers" />
          <VCTile icon={Building2} label="Brand owners & bottlers" detail="Coca-Cola, PepsiCo, Tan Hiep Phat" primary />
          <VCTile icon={Truck} label="Distributors" detail="Move product to tens of thousands of outlets" />
          <VCTile icon={Store} label="Retailers" detail="Mom-and-pop shops, supermarkets, convenience" />
          <VCTile icon={Users} label="Consumers" detail="The final buyer who realises the value" />
          <VCTile icon={ShieldCheck} label="Regulators" detail="Food-safety, labelling and tax authorities" />
        </div>
      </div>
      <VCNote label="Supporting cast:">Marketing agencies, logistics and cold-chain providers, and industry associations all shape how the drink reaches the shelf.</VCNote>
    </VCFrame>
  );
}

function NabDef2CharacteristicsVisual() {
  return (
    <VCFrame
      title="What Makes Beverages Distinctive"
      subtitle="Six characteristics that shape how beverage companies compete."
      takeaway="Beverages win on brand, availability and distribution reach as much as on the liquid itself."
    >
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        <VCTile icon={Sparkles} label="Brand-intensive" detail="Recognition and trust drive the purchase" primary />
        <VCTile icon={Target} label="Impulse-driven" detail="Often bought on the spot, cold and nearby" />
        <VCTile icon={Truck} label="High-velocity FMCG" detail="Low price, huge volume, frequent repeat" />
        <VCTile icon={Store} label="Distribution as a moat" detail="Reaching every small shop is decisive" primary />
        <VCTile icon={DollarSign} label="Packaging-heavy economics" detail="The package can cost more than the liquid" />
        <VCTile icon={ThermometerSun} label="Cold chain matters" detail="Ice-cold and at arm's reach wins the sale" />
      </div>
      <VCNote label="Commercial implication:">Because loyalty is fragile, brands invest continuously in marketing and in getting their product within arm's reach.</VCNote>
    </VCFrame>
  );
}

function NabDef3ScopeVisual() {
  return (
    <VCFrame
      title="Where the Industry Begins and Ends"
      subtitle="What counts as a non-alcoholic beverage, what sits next door, and what is excluded."
      takeaway="The boundary is drawn at under 0.5% alcohol; where you draw the line changes the market size you report."
    >
      <div className="grid gap-3 lg:grid-cols-3">
        <VCList icon={CheckCircle} title="In scope" label="Non-alcoholic, below 0.5% ABV" primary items={['Bottled & flavoured water', 'Carbonated soft drinks', 'Juices & juice drinks', 'RTD tea & coffee', 'Energy & sports drinks', 'Plant-based & functional drinks']} />
        <VCList icon={ArrowRight} title="Adjacent" label="Overlapping categories" items={['Drinkable dairy & yogurt', 'Cafe & foodservice drinks', 'Supplements & wellness shots']} />
        <VCList icon={X} title="Out of scope" label="Excluded" items={['Beer, wine and spirits', 'Traditional fermented alcoholic drinks', 'Any drink at or above 0.5% ABV']} />
      </div>
      <VCNote label="Why totals differ:">Research firms include or exclude juices and dairy-based drinks differently, so reported market sizes vary widely.</VCNote>
    </VCFrame>
  );
}

function NabDef4TaxonomyVisual() {
  const groups: { label: string; icon: LucideIcon; examples: string; primary?: boolean }[] = [
    { label: 'Water', icon: Globe, examples: 'Still, sparkling, flavoured — Aquafina, La Vie, Dasani' },
    { label: 'Carbonated soft drinks', icon: Store, examples: 'Coca-Cola, Pepsi, 7Up, Sprite', primary: true },
    { label: 'Juices', icon: Sprout, examples: 'Fruit juice and juice drinks' },
    { label: 'RTD tea & coffee', icon: Target, examples: 'C2, Tea+, canned coffee', primary: true },
    { label: 'Energy & sports', icon: Lightbulb, examples: 'Sting, Number 1, Red Bull, Pocari Sweat' },
    { label: 'Plant-based & functional', icon: Sparkles, examples: 'Soy/oat drinks, probiotics, electrolytes' },
  ];
  return (
    <VCFrame
      title="The Beverage Product Landscape"
      subtitle="The major families of non-alcoholic drinks and what sits inside each."
      takeaway="Companies run portfolios across these families to cover different price tiers, tastes and occasions."
    >
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {groups.map((g) => (
          <VCTile key={g.label} icon={g.icon} label={g.label} detail={g.examples} primary={g.primary} />
        ))}
      </div>
      <VCNote label="Vietnam tilt:">RTD tea is the single largest category by volume in Vietnam, and RTD coffee is the fastest-growing.</VCNote>
    </VCFrame>
  );
}

function NabDef5MatrixVisual() {
  const rows: { occasion: string; need: string; drink: string }[] = [
    { occasion: 'On the go', need: 'Quick refreshment', drink: 'Chilled water, CSD, RTD tea' },
    { occasion: 'With a meal', need: 'Complement food', drink: 'CSD, juice, tea' },
    { occasion: 'Study / work', need: 'Focus & energy', drink: 'RTD coffee, energy drinks' },
    { occasion: 'After exercise', need: 'Hydration & recovery', drink: 'Sports & electrolyte drinks' },
    { occasion: 'Social & gifting', need: 'Share & treat', drink: 'Premium packs, functional drinks' },
  ];
  return (
    <VCFrame
      title="Who Drinks What — and Why"
      subtitle="Match the occasion and the underlying need to the drink people reach for."
      takeaway="Demand is driven by the occasion and the need behind it, not just the brand on the label."
    >
      <div className="overflow-x-auto">
        <div className="min-w-[560px] space-y-2">
          <div className="grid grid-cols-[1fr_1fr_1.3fr] gap-2 px-1 text-[10px] font-black uppercase tracking-[0.12em] text-slate-400">
            <span>Occasion</span><span>Core need</span><span>Typical drinks</span>
          </div>
          {rows.map((r, i) => (
            <div key={r.occasion} className={`grid grid-cols-[1fr_1fr_1.3fr] items-center gap-2 rounded-2xl border bg-white p-3 ${i === 0 ? 'border-red-300' : 'border-slate-200'}`}>
              <p className="text-xs font-black text-slate-900">{r.occasion}</p>
              <p className="text-[11px] leading-4 text-slate-600">{r.need}</p>
              <p className="text-[11px] leading-4 text-slate-500">{r.drink}</p>
            </div>
          ))}
        </div>
      </div>
      <div>
        <VCLabel>What drives the choice</VCLabel>
        <div className="mt-2"><VCChips items={['Taste', 'Availability (cold & nearby)', 'Price', 'Health perception', 'Convenience']} primary /></div>
      </div>
    </VCFrame>
  );
}

function NabHistTimeline({ items }: { items: { year: string; title: string; detail: string; primary?: boolean }[] }) {
  return (
    <div className="relative pl-6">
      <span className="absolute left-[7px] top-2 bottom-2 w-0.5 bg-red-100" aria-hidden />
      <div className="space-y-3">
        {items.map((it) => (
          <div key={`${it.year}-${it.title}`} className="relative">
            <span className={`absolute -left-[22px] top-2 flex h-3.5 w-3.5 items-center justify-center rounded-full ring-2 ring-white ${it.primary ? 'bg-red-600' : 'bg-red-300'}`} aria-hidden />
            <div className={`rounded-2xl border bg-white p-3 ${it.primary ? 'border-red-300' : 'border-slate-200'}`}>
              <div className="flex flex-wrap items-center gap-2">
                <span className={`rounded-full px-2 py-0.5 text-[11px] font-bold tabular-nums ${it.primary ? 'bg-red-600 text-white' : 'bg-red-50 text-red-600 ring-1 ring-red-100'}`}>{it.year}</span>
                <p className="text-sm font-black leading-5 text-slate-900">{it.title}</p>
              </div>
              <p className="mt-1 text-xs leading-5 text-slate-500">{it.detail}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function NabHist1OriginsVisual() {
  return (
    <VCFrame
      title="From First Fizz to the First Bottling Plant"
      subtitle="How carbonated water became a branded, commercially produced industry."
      takeaway="A scientific discovery (carbonation) plus a commercial model (branding and bottling) turned a novelty into an industry."
    >
      <NabHistTimeline items={[
        { year: '1767', title: 'Carbonated water is invented', detail: 'Joseph Priestley artificially carbonates water — the scientific starting point for soft drinks.' },
        { year: '1885', title: 'Dr Pepper is created', detail: 'One of the first branded soft drinks appears in the United States.' },
        { year: '1886', title: 'Coca-Cola is founded', detail: 'John Stith Pemberton creates Coca-Cola in Atlanta, Georgia — the brand that comes to define the category.', primary: true },
        { year: '1899', title: 'The first bottling plant opens', detail: 'Coca-Cola is first bottled in Chattanooga, Tennessee, beginning organised, large-scale production.' },
      ]} />
      <VCNote label="Why it matters:">Early drinks were mixed at soda fountains; bottling made beverages portable, consistent and sellable far beyond one city.</VCNote>
    </VCFrame>
  );
}

function NabHist2TechnologyVisual() {
  const rows: { tech: string; icon: LucideIcon; impact: string; primary?: boolean }[] = [
    { tech: 'Carbonation', icon: Sparkles, impact: 'Created the fizzy soft-drink category itself' },
    { tech: 'Bottling & franchise bottling', icon: Building2, impact: 'Let one brand be produced and sold worldwide', primary: true },
    { tech: 'Pasteurisation & quality control', icon: ShieldCheck, impact: 'Made drinks safe and consistent at scale' },
    { tech: 'Packaging: glass to cans to PET', icon: Store, impact: 'Cut cost and weight and widened distribution' },
    { tech: 'Aseptic processing', icon: Cpu, impact: 'Shelf-stable, preservative-free RTD without a cold chain', primary: true },
  ];
  return (
    <VCFrame
      title="Technologies That Changed Beverage Production"
      subtitle="Each innovation unlocked a new way to make, protect, or distribute drinks."
      takeaway="Beverage history is driven by production technology: each breakthrough widened what could be sold and where."
    >
      <div className="space-y-2">
        {rows.map(({ tech, icon: Icon, impact, primary }) => (
          <div key={tech} className={`grid items-center gap-2 rounded-2xl border bg-white p-3 sm:grid-cols-[1.1fr_auto_1.2fr] ${primary ? 'border-red-300' : 'border-slate-200'}`}>
            <div className="flex items-center gap-2">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-red-50 text-red-600"><Icon className="h-4 w-4" /></span>
              <p className="text-xs font-black leading-4 text-slate-900">{tech}</p>
            </div>
            <ArrowRight className="hidden h-4 w-4 text-red-400 sm:block" />
            <p className="rounded-xl bg-red-50 p-2 text-[11px] font-semibold leading-4 text-slate-700">{impact}</p>
          </div>
        ))}
      </div>
      <VCNote label="Vietnam note:">Tan Hiep Phat's adoption of aseptic technology in the mid-2000s is a local example of this exact shift.</VCNote>
    </VCFrame>
  );
}

function NabHist3GlobalVisual() {
  return (
    <VCFrame
      title="How Global Beverage Brands Rose"
      subtitle="From franchise bottling to the cola wars, energy drinks, and ready-to-drink categories."
      takeaway="Global scale came from the franchise model, mass marketing, and a steady stream of new categories."
    >
      <NabHistTimeline items={[
        { year: '1900s', title: 'Franchise bottling goes global', detail: 'Coca-Cola and later Pepsi expand worldwide by licensing local bottlers.', primary: true },
        { year: '1960s-70s', title: "Japan's RTD revolution", detail: 'Suntory and Kirin pioneer ready-to-drink canned coffee and tea — the format that now leads Asian markets.' },
        { year: '1970s-80s', title: 'The Cola Wars', detail: 'Coca-Cola versus Pepsi defines modern FMCG competition and mass TV advertising.' },
        { year: '1987', title: 'Red Bull launches', detail: 'Dietrich Mateschitz reworks Thai Krating Daeng into Red Bull, creating the modern energy-drink category.', primary: true },
        { year: '2002', title: 'Monster enters energy', detail: 'Monster Beverage expands the fast-growing energy segment.' },
        { year: '2025', title: 'The health pivot', detail: 'PepsiCo buys prebiotic soda Poppi (about $1.95B) and Coca-Cola launches Simply Pop, betting on functional drinks.' },
      ]} />
      <VCNote label="Why it matters:">Each wave — cola, RTD, energy, functional — created a new category and a new set of global winners.</VCNote>
    </VCFrame>
  );
}

function NabHist4VietnamVisual() {
  return (
    <VCFrame
      title="The Making of Vietnam's Beverage Industry"
      subtitle="From market liberalisation to global entrants and strong local champions."
      takeaway="Doi Moi opened the door; global brands and local champions then built the modern market together."
    >
      <NabHistTimeline items={[
        { year: '1986', title: 'Doi Moi reform', detail: 'Market liberalisation opens Vietnam to foreign investment and private enterprise.' },
        { year: '1994', title: 'Global brands enter', detail: 'Coca-Cola and PepsiCo arrive; Tan Hiep Phat (THP) is founded the same year.', primary: true },
        { year: '2001', title: 'A local champion rises', detail: 'THP launches Number 1 Energy Drink, a breakout domestic success.' },
        { year: '2003', title: 'RTD tea takes off', detail: 'URC enters with C2 green tea, helping make RTD tea the defining format in Vietnam.' },
        { year: 'Mid-2000s', title: 'Aseptic technology moat', detail: 'THP adopts aseptic lines for preservative-free, shelf-stable drinks — a lasting distribution edge.' },
        { year: '2013', title: 'Suntory PepsiCo forms', detail: 'The SPVB joint venture (Suntory 51% / PepsiCo 49%) consolidates a market leader.', primary: true },
      ]} />
      <VCNote label="Where it stands:">Today global multinationals and domestic champions compete across RTD tea, CSDs, water and energy drinks.</VCNote>
    </VCFrame>
  );
}

