function NabModuleOneVisual({ kind }: { kind: string }) {
  const data = NAB_MODULE_ONE_VISUALS[kind];
  if (!data) return null;
  return (
    <VCFrame title={data.title} subtitle={data.subtitle} takeaway={data.takeaway}>
      {data.mode === 'flow' && <VCFlow nodes={data.items.map((item, index) => ({ label: item.label, detail: item.detail, primary: index === 0 }))} />}
      {data.mode === 'bars' && (
        <div className="space-y-3 rounded-2xl border border-slate-200 bg-white p-4">
          {data.items.map((item) => (
            <div key={item.label}>
              <div className="flex items-baseline justify-between gap-3"><div><p className="text-xs font-black text-slate-900">{item.label}</p><p className="text-[11px] leading-4 text-slate-500">{item.detail}</p></div><p className="shrink-0 text-sm font-black text-red-600">{item.value}</p></div>
              <div className="mt-2 h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-red-600" style={{ width: `${item.pct ?? 0}%` }} /></div>
            </div>
          ))}
        </div>
      )}
      {data.mode === 'table' && (
        <div className="overflow-x-auto rounded-2xl border border-slate-200">
          <table className="w-full min-w-[600px] border-collapse text-left">
            <thead className="bg-red-600 text-white"><tr><th className="px-4 py-3 text-xs font-black">Category</th><th className="px-4 py-3 text-xs font-black">Plain-language read</th><th className="px-4 py-3 text-xs font-black">Signal</th></tr></thead>
            <tbody>{data.items.map((item, index) => <tr key={item.label} className={index % 2 ? 'bg-slate-50' : 'bg-white'}><th className="px-4 py-3 text-xs font-black text-slate-900">{item.label}</th><td className="px-4 py-3 text-xs leading-5 text-slate-600">{item.detail}</td><td className="px-4 py-3 text-xs font-bold text-red-600">{item.value}</td></tr>)}</tbody>
          </table>
        </div>
      )}
      {data.note && <VCNote label="Read with care:">{data.note}</VCNote>}
    </VCFrame>
  );
}

const NAB_DEF_VISUALS = {
  'nab-def-1-ecosystem': NabDef1EcosystemVisual,
  'nab-def-2-characteristics': NabDef2CharacteristicsVisual,
  'nab-def-3-scope': NabDef3ScopeVisual,
  'nab-def-4-taxonomy': NabDef4TaxonomyVisual,
  'nab-def-5-matrix': NabDef5MatrixVisual,
  'nab-def-hist-1-origins': NabHist1OriginsVisual,
  'nab-def-hist-2-technology': NabHist2TechnologyVisual,
  'nab-def-hist-3-global': NabHist3GlobalVisual,
  'nab-def-hist-4-vietnam': NabHist4VietnamVisual,
} as const;

type NabDefVisualKind = keyof typeof NAB_DEF_VISUALS;

function renderNabDefVisual(kind: string): ReactNode {
  if (kind.startsWith('nab-def-m1-')) return <NabModuleOneVisual kind={kind} />;
  const render = (NAB_DEF_VISUALS as Record<string, () => ReactNode>)[kind];
  return render ? render() : null;
}

