const nabContextCard = (data: {
  title: string;
  objective: string;
  intro: string;
  insight: string;
  tiles: StatTile[];
  what: string;
  how: string;
  example: string;
  why: string;
  visualKind: `nab-def-m1-${string}`;
  visualHeading: string;
  terms: LearningTerm[];
  recap: string[];
  sources: string[];
}): FlashcardData => ({
  title: data.title,
  readingTime: '4',
  objective: data.objective,
  mateIntro: data.intro,
  keyInsight: data.insight,
  statTiles: data.tiles,
  concepts: [
    { title: 'What it is', summary: data.what, whyItMatters: data.why, icon: BookOpen },
    { title: 'How it works', summary: `${data.how}\n\nIn practice: ${data.example}`, icon: Workflow },
  ],
  visualKind: data.visualKind,
  visualHeading: data.visualHeading,
  visualIntro: 'Use the visual to connect the chapter’s key market signals without losing the definition behind each number.',
  imageAlt: `Casemate learning visual for ${data.title}`,
  keyTerms: data.terms,
  recap: data.recap,
  deepDiveTitle: 'Dive deeper and review sources',
  body: (
    <div className="space-y-5">
      <section><h4 className="font-extrabold text-slate-900">What it is</h4><p className="mt-1">{data.what}</p></section>
      <section><h4 className="font-extrabold text-slate-900">How it works</h4><p className="mt-1">{data.how}</p></section>
      <section><h4 className="font-extrabold text-slate-900">Real-world example</h4><p className="mt-1">{data.example}</p></section>
      <section><h4 className="font-extrabold text-slate-900">Why it matters</h4><p className="mt-1">{data.why}</p></section>
      <section><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-red-600">Source references</p><ul className="mt-2 list-disc space-y-1 pl-5 text-xs leading-6 text-slate-500">{data.sources.map((source) => <li key={source}>{source}</li>)}</ul></section>
    </div>
  ),
});

