function CategoryCard({ category, onOpen, comingSoon = false }: { category: IndustryCategory; onOpen: () => void; comingSoon?: boolean }) {
  const Icon = category.icon;
  return (
    <button type="button" onClick={onOpen}
      className="group flex min-h-40 flex-col rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm transition-all hover:-translate-y-0.5 hover:border-red-200 hover:shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500"
      data-testid={`industry-category-${category.id}`}>
      <div className="flex items-start justify-between gap-3">
        <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-red-50 text-red-600"><Icon className="h-5 w-5" /></span>
        {comingSoon ? <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-medium text-slate-400">Coming Soon</span> : <ArrowRight className="h-4 w-4 text-slate-300 transition-transform group-hover:translate-x-1 group-hover:text-red-500" />}
      </div>
      <div className={comingSoon ? 'opacity-75' : undefined}>
        <h2 className="mt-3 text-sm font-bold text-slate-900">{category.name}</h2>
        <p className="mt-1.5 text-xs leading-5 text-slate-500">{category.description}</p>
      </div>
      <span className="mt-auto pt-3 text-[11px] font-semibold text-red-600">{comingSoon ? 'Preview coverage →' : 'Explore knowledge →'}</span>
    </button>
  );
}

function KnowledgeCardItem({ kind, card, onOpen, fluid = false, inDevelopment = false }: { kind: KnowledgeKind; card: KnowledgeCard; onOpen: () => void; fluid?: boolean; inDevelopment?: boolean }) {
  const ModuleIcon = MODULE_ICONS[card.title] ?? BookOpen;
  const isIndustry = kind === 'Industry';
  return (
    <button type="button" onClick={() => openKnowledgeDestination('Loading knowledge content...', onOpen)}
      className={`group flex ${fluid ? 'w-full' : 'w-full'} flex-col rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm transition-all hover:-translate-y-0.5 hover:border-red-200 hover:shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500`}
      aria-label={`Open ${card.primaryTitle ?? card.title}`}>
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-2">
          {card.moduleNumber && <span className="text-[11px] font-bold text-slate-400">{card.moduleNumber}</span>}
          <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-red-50 text-red-600"><ModuleIcon className="h-4 w-4" /></span>
        </div>
        {inDevelopment ? <span className="rounded-full bg-amber-100 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-amber-800">In Development</span> : <ArrowRight className="h-4 w-4 shrink-0 text-slate-300 transition-transform group-hover:translate-x-1 group-hover:text-red-500" />}
      </div>
      {isIndustry && card.primaryTitle ? <><h3 className="mt-3 text-sm font-bold text-slate-900">{card.primaryTitle}</h3><p className="mt-0.5 text-xs text-slate-500">{card.title}</p></> : <h3 className="mt-3 text-sm font-bold text-slate-900">{card.title}</h3>}
      <p className="mt-2 line-clamp-3 text-xs leading-5 text-slate-500">{card.description}</p>
      <span className="mt-auto pt-4 text-[11px] font-semibold text-red-600">{isIndustry ? (inDevelopment ? 'View lesson plan →' : 'Start learning →') : 'Explore topic →'}</span>
    </button>
  );
}

function KnowledgeSectionBlock({ section, industryName: _industryName, industryId, onOpenCard }: { section: KnowledgeSection; industryName: string; industryId?: string; onOpenCard: (card: KnowledgeCard) => void }) {
  return (
    <section aria-labelledby={`${section.kind.toLowerCase()}-knowledge-heading`}>
      <h2 id={`${section.kind.toLowerCase()}-knowledge-heading`} className="sr-only">{section.title}</h2>
      <div className="mt-6 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3" data-testid={`${section.kind.toLowerCase()}-knowledge-cards`}>
        {section.cards.map((card) => (
          <KnowledgeCardItem
            key={card.title}
            kind={section.kind}
            card={section.kind === 'Industry' ? resolveIndustryKnowledgeCard(card, industryId) : card}
            onOpen={() => onOpenCard(card)}
            inDevelopment={section.kind === 'Industry' && isCommercialBankingModuleInDevelopment(industryId, card.title)}
          />
        ))}
      </div>
    </section>
  );
}

