const bmVisual = (title: string): BmVisualData => {
  const base = BM_EXTRAS[title].visual;
  const style = BM_VISUAL_STYLE[title];
  return {
    ...base,
    variant: style.variant,
    compareLabels: style.compareLabels,
    nodes: base.nodes.map((node, index) => ({ ...node, icon: style.icons?.[index], tone: style.tones?.[index] })),
  };
};

