const BM_CONCEPT_ICONS: LucideIcon[] = [Building2, Landmark, ShieldCheck, Truck, BarChart3, Users];

const bmTile = (label: string, description: string, subtitle?: string): StatTile => ({ label, subtitle, description });

const bmChapter = (chapter: {
  title: string;
  objective: string;
  intro: string;
  insight: string;
  tiles: StatTile[];
  dataKey?: string;
  tileOffset?: number;
  recap: string;
}): FlashcardData => {
  const extras = BM_EXTRAS[chapter.title];
  return {
    title: chapter.title,
    objective: chapter.objective,
    mateIntro: chapter.intro,
    keyInsight: chapter.insight,
    statTiles: extras.stats,
    statsNote: extras.statsNote,
    concepts: chapter.tiles.map((tile, index) => ({
      title: tile.label,
      technicalLabel: extras.plain ? undefined : tile.subtitle ?? extras.group,
      groupLabel: extras.plain ? tile.subtitle ?? extras.group : undefined,
      summary: tile.description,
      icon: BM_CONCEPT_ICONS[index % BM_CONCEPT_ICONS.length],
      points: BM_CARD_DEEP[chapter.dataKey ?? chapter.title]?.[index + (chapter.tileOffset ?? 0)]?.[0],
      whyItMatters: BM_CARD_MORE[chapter.dataKey ?? chapter.title]?.[index + (chapter.tileOffset ?? 0)]?.[0],
      industryDetail: BM_CARD_MORE[chapter.dataKey ?? chapter.title]?.[index + (chapter.tileOffset ?? 0)]?.[1] ?? BM_CARD_DEEP[chapter.dataKey ?? chapter.title]?.[index + (chapter.tileOffset ?? 0)]?.[1],
    })),
    visualData: bmVisual(chapter.title),
    visualHeading: extras.visual.title,
    visualIntro: "Use this framework to connect the chapter's key ideas at a glance.",
    imageAlt: `Casemate framework visual: ${extras.visual.title}`,
    keyTerms: BM_MORE[chapter.title].terms,
    chapterWhy: BM_MORE[chapter.title].why,
    recap: chapter.recap.split(/(?<=\.)\s+/),
    body: (
      <div className="space-y-4">
        <p>{chapter.intro}</p>
        <p>{chapter.insight}</p>
      </div>
    ),
    deepDiveTitle: "Full explanation",
    readingTime: '2',
  };
};

