/**
 * Dairy full-curriculum reconciliation.
 *
 * The original 87 cards remain above as the evidence/content archive. This registry
 * deterministically rebalances them inside their existing lesson namespaces, so no
 * learner state has to cross a persistence key. Consolidated cards retain every
 * original body, concept, term, recap and citation; added positions isolate a distinct
 * objective from a rich source card and intentionally inherit no completion.
 */
interface DairyLessonSpec {
  module: '01' | '02' | '03' | '04' | '05';
  moduleTitle: string;
  lesson: string;
  source: FlashcardData[];
  titles: string[];
}

const DAIRY_REFERENCE_SOURCES: Array<{ title: string; href: string; publisher: string }> = [
  { title: 'FAOSTAT — Crops and livestock products', href: 'https://www.fao.org/faostat/en/#data/QCL', publisher: 'Food and Agriculture Organization of the United Nations' },
  { title: 'OECD-FAO Agricultural Outlook', href: 'https://www.oecd.org/en/publications/oecd-fao-agricultural-outlook_19991142.html', publisher: 'OECD and FAO' },
  { title: 'National Statistics Office of Vietnam', href: 'https://www.nso.gov.vn/en/homepage/', publisher: 'National Statistics Office of Vietnam' },
  { title: 'Codex Alimentarius — Milk and milk products', href: 'https://www.fao.org/fao-who-codexalimentarius/thematic-areas/milk-and-milk-products/en/', publisher: 'FAO and World Health Organization' },
  { title: 'Vinamilk investor relations', href: 'https://www.vinamilk.com.vn/en/investor-relations/', publisher: 'Vietnam Dairy Products Joint Stock Company' },
];

function dairyLegacyTargets(lesson: string, sourceCount: number, targetCount: number): number[] {
  if (sourceCount === targetCount) return Array.from({ length: sourceCount }, (_, index) => index);
  if (lesson === 'What the Industry Includes' && sourceCount === 3 && targetCount === 5) return [0, 3, 4];
  if (sourceCount === 2 && targetCount === 4) return [0, 3];
  if (sourceCount === 3 && targetCount === 5) return [0, 2, 4];
  if (sourceCount === 7 && targetCount === 5) return [0, 0, 1, 2, 3, 3, 4];
  if (sourceCount === 2 && targetCount === 3) return [0, 2];
  if (sourceCount === 4 && targetCount === 3) return [0, 1, 1, 2];
  return Array.from({ length: sourceCount }, (_, index) => sourceCount === 1 ? 0 : Math.round((index * (targetCount - 1)) / (sourceCount - 1)));
}

const dairyUniqueBy = <T,>(items: T[], key: (item: T) => string): T[] => Array.from(new Map(items.map((item) => [key(item), item])).values());

function rebalanceDairyLesson(spec: DairyLessonSpec): FlashcardData[] {
  const targets = dairyLegacyTargets(spec.lesson, spec.source.length, spec.titles.length);
  const legacyGroups = spec.titles.map(() => [] as number[]);
  targets.forEach((target, legacyIndex) => legacyGroups[Math.max(0, Math.min(spec.titles.length - 1, target))].push(legacyIndex));

  return spec.titles.map((canonicalTitle, index) => {
    const legacyIndexes = legacyGroups[index];
    const fallbackIndex = Math.min(spec.source.length - 1, Math.floor((index * spec.source.length) / spec.titles.length));
    const resolvedBaseIndex = legacyIndexes[0] ?? fallbackIndex;
    const base = spec.source[resolvedBaseIndex];
    const legacyCards = legacyIndexes.map((legacyIndex) => spec.source[legacyIndex]);
    const contentCards = legacyCards.length ? legacyCards : [base];
    const allConcepts = contentCards.flatMap((card) => card.concepts ?? []);
    const sourceTargetIndexes = spec.titles.map((_, targetIndex) => legacyGroups[targetIndex][0] ?? Math.min(spec.source.length - 1, Math.floor((targetIndex * spec.source.length) / spec.titles.length)));
    const siblingTargets = sourceTargetIndexes.map((sourceIndex, targetIndex) => ({ sourceIndex, targetIndex })).filter((item) => item.sourceIndex === resolvedBaseIndex);
    const siblingRank = Math.max(0, siblingTargets.findIndex((item) => item.targetIndex === index));
    const isSplitExpansion = spec.source.length < spec.titles.length && siblingTargets.length > 1;
    const concepts = isSplitExpansion && base.concepts.length
      ? [base.concepts[siblingRank % base.concepts.length]]
      : legacyCards.length
        ? allConcepts
        : base.concepts;
    const primaryConcept = concepts[0];
    const keyTerms = dairyUniqueBy(contentCards.flatMap((card) => card.keyTerms ?? []), (term) => term.term);
    const inheritedRecap = Array.from(new Set(contentCards.flatMap((card) => card.recap ?? []).filter(Boolean)));
    const recap = isSplitExpansion && primaryConcept
      ? [primaryConcept.summary ?? base.keyInsight, primaryConcept.whyItMatters ?? base.objective].filter(Boolean)
      : inheritedRecap;
    const inheritedSources = dairyUniqueBy(contentCards.flatMap((card) => card.sources ?? []), (source) => source.href);
    const sources = dairyUniqueBy([...inheritedSources, ...DAIRY_REFERENCE_SOURCES.slice(spec.module === '01' ? 0 : 1, spec.module === '01' ? 4 : 5)], (source) => source.href);
    const conceptNodes = concepts.slice(0, 5).map((concept) => ({ label: concept.title, note: concept.summary ?? concept.whyItMatters, icon: 'milk' }));
    const visualNodes = conceptNodes.length ? conceptNodes : contentCards.slice(0, 5).map((card) => ({ label: displayChapterTitle(card.title), note: card.objective, icon: 'milk' }));
    const narrative = isSplitExpansion ? [] : contentCards.flatMap((card) => card.narrative ?? []);
    const mergedBody = isSplitExpansion && primaryConcept ? (
      <div className="space-y-4">
        {primaryConcept.summary && <p>{primaryConcept.summary}</p>}
        {primaryConcept.points?.map((point) => <p key={point}>{point}</p>)}
        {primaryConcept.industryDetail && <p>{primaryConcept.industryDetail}</p>}
        {primaryConcept.whyItMatters && <p><strong>Why it matters: </strong>{primaryConcept.whyItMatters}</p>}
      </div>
    ) : (
      <div className="space-y-5">
        {contentCards.map((card, sourceIndex) => (
          <section key={`${card.title ?? 'legacy'}-${sourceIndex}`}>
            {contentCards.length > 1 && <h4 className="font-extrabold text-slate-900">Preserved from: {displayChapterTitle(card.title)}</h4>}
            <div className={contentCards.length > 1 ? 'mt-2' : ''}>{card.body ?? <p>{card.keyInsight}</p>}</div>
          </section>
        ))}
      </div>
    );

    return {
      ...base,
      title: `${String(index + 1).padStart(2, '0')} ${canonicalTitle}`,
      objective: `Explain ${canonicalTitle.toLowerCase()} and apply it to dairy-industry decisions.`,
      mateIntro: `Connect this chapter to a practical dairy decision: ${base.mateIntro ?? base.objective}`,
      keyInsight: isSplitExpansion ? primaryConcept?.whyItMatters ?? primaryConcept?.summary ?? base.keyInsight : contentCards.map((card) => card.keyInsight).filter(Boolean).join(' '),
      concepts,
      narrative: narrative.length ? narrative : [
        { label: 'What it is', text: primaryConcept?.summary ?? base.objective },
        { label: 'How it works', text: primaryConcept?.points?.join(' ') ?? base.keyInsight },
        { label: 'Example', text: primaryConcept?.industryDetail ?? recap[0] ?? base.keyInsight },
        { label: 'Why it matters', text: primaryConcept?.whyItMatters ?? recap[1] ?? base.keyInsight },
      ],
      body: mergedBody,
      keyTerms,
      recap: recap.length ? recap : [base.keyInsight],
      chapterRecap: (recap.length ? recap : [base.keyInsight]).join(' '),
      sources,
      stats: contentCards.flatMap((card) => card.stats ?? []).slice(0, 3),
      statTiles: contentCards.flatMap((card) => card.statTiles ?? []).slice(0, 4),
      visualKind: undefined,
      visualHeading: canonicalTitle,
      visualIntro: `Use this chapter-specific framework to connect ${canonicalTitle.toLowerCase()} to product quality, customer value, operating economics, and risk.`,
      visualData: {
        title: canonicalTitle,
        subtitle: `${spec.moduleTitle} · ${spec.lesson}`,
        variant: spec.module === '02' ? 'flow' : 'cards',
        flow: spec.module === '02' ? visualNodes.map((node) => node.label) : undefined,
        nodes: visualNodes,
        takeaway: contentCards[0].keyInsight,
      },
      imageAlt: `Casemate dairy learning visual for ${canonicalTitle}`,
      legacyIndex: legacyIndexes[0],
      legacyIndexes,
      legacyCompletionIndex: legacyIndexes[0],
      migrationVersion: 'dairy-full-v1',
    };
  });
}

