const DAIRY_STANDARD_DECKS: Record<string, Record<string, FlashcardData[]>> = { '01': {}, '02': {}, '03': {}, '04': {}, '05': {} };
DAIRY_LESSON_SPECS.forEach((spec) => { DAIRY_STANDARD_DECKS[spec.module][spec.lesson] = rebalanceDairyLesson(spec); });

const dairyStorageKey = (spec: DairyLessonSpec) => spec.module === '01'
  ? spec.lesson === 'What the Industry Includes' ? 'Industry Definition & Scope' : `Dairy Industry Context: ${spec.lesson}`
  : spec.module === '02' ? `Dairy Value Chain: ${spec.lesson}`
  : spec.module === '03' ? `Dairy How Companies Make Money: ${spec.lesson}`
  : spec.module === '04' ? `Dairy Who Competes—and Why They Win: ${spec.lesson}`
  : `Dairy What Is Changing Next: ${spec.lesson}`;

const DAIRY_LEGACY_CHAPTER_MAP = DAIRY_LESSON_SPECS.flatMap((spec) => {
  const deck = DAIRY_STANDARD_DECKS[spec.module][spec.lesson];
  return spec.source.map((card, legacyIndex) => {
    const destinationIndex = deck.findIndex((nextCard) => nextCard.legacyIndexes?.includes(legacyIndex));
    return {
      oldModule: spec.module,
      oldLesson: spec.lesson,
      oldIndex: legacyIndex,
      oldTitle: displayChapterTitle(card.title),
      oldObjective: card.objective,
      newModule: spec.module,
      newLesson: spec.lesson,
      newIndex: destinationIndex,
      newTitle: displayChapterTitle(deck[destinationIndex]?.title),
      sourceTitles: (card.sources ?? []).map((source) => source.title),
      oldStorageKey: dairyStorageKey(spec),
      targetStorageKey: dairyStorageKey(spec),
      migrationBehavior: deck[destinationIndex]?.legacyIndexes?.length > 1 ? 'MERGE_WITH_PROVENANCE' : 'KEEP_OR_EXPAND',
    };
  });
});

const DAIRY_RESTRUCTURE_AUDIT = {
  originalChapters: DAIRY_LEGACY_CHAPTER_MAP.length,
  finalChapters: DAIRY_LESSON_SPECS.reduce((sum, spec) => sum + spec.titles.length, 0),
  moduleBefore: Object.fromEntries(['01', '02', '03', '04', '05'].map((module) => [module, DAIRY_LESSON_SPECS.filter((spec) => spec.module === module).reduce((sum, spec) => sum + spec.source.length, 0)])),
  moduleAfter: Object.fromEntries(['01', '02', '03', '04', '05'].map((module) => [module, DAIRY_LESSON_SPECS.filter((spec) => spec.module === module).reduce((sum, spec) => sum + spec.titles.length, 0)])),
  legacyMap: DAIRY_LEGACY_CHAPTER_MAP,
};
void DAIRY_RESTRUCTURE_AUDIT;

/**
 * Chapter placement for the Dairy lessons whose dairy-full-v1 re-chaptering added chapters, checked
 * against the text each NEW chapter displays: [question id, NEW lesson-local chapter]. A source chapter
 * split across several new chapters sends each question to the chapter that teaches it, legacy
 * questions whose facts the lesson no longer shows are left out, and DAIRY_NEW_CHAPTER_QUIZZES seeds
 * cover chapters no legacy question tests, keeping the lesson at 10 questions where the bank allows.
 */
