function DomainKnowledgeScreen() {
  const { trackEvent } = useSpaceRuntime();
  const openedRef = useRef(false);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [route, setRoute] = useState<DomainKnowledgeRoute>(() => readDomainKnowledgeRoute());
  const [knowledgeTransition, setKnowledgeTransition] = useState<KnowledgeNavigationState | null>(null);

  const navigate = useCallback((nextRoute: DomainKnowledgeRoute, replace = false) => {
    writeDomainKnowledgeRoute(nextRoute, replace);
    setRoute(nextRoute);
  }, []);
  const [basicEconomicsRoute, setBasicEconomicsRoute] = useState<BasicEconomicsRoute | null>(null);
  const [learningModeAudit, setLearningModeAudit] = useState(() => {
    try {
      return new URLSearchParams(window.location.search).get('dkAudit') === 'learning-modes';
    } catch {
      return false;
    }
  });
  const closeLearningModeAudit = () => {
    setLearningModeAudit(false);
    try {
      const url = new URL(window.location.href);
      url.searchParams.delete('dkAudit');
      window.history.replaceState({}, '', url);
    } catch {
      // The panel closes either way.
    }
  };

  // Other apps (Case Pool framework link, My Roadmap) hand over a destination through a one-shot
  // session key. Read it when this screen opens, and again when the app is already open and the
  // dock event arrives. With no key nothing changes.
  useEffect(() => {
    const consumePendingRoute = () => {
      const pending = takeDomainPendingRoute();
      if (!pending) return;
      if (pending.industrySlug === BASIC_ECONOMICS_SLUG) {
        setBasicEconomicsRoute({ pillar: pending.pillar, cardTitle: pending.cardTitle, cardId: pending.cardId, nonce: Date.now() });
        return;
      }
      const sector = resolveSectorRoute(pending, (categoryId) => AVAILABLE_CATEGORY_IDS.includes(categoryId));
      if (!sector) return;
      setBasicEconomicsRoute(null);
      navigate({ groupId: sector.groupId, categoryId: sector.categoryId, tab: sector.categoryId ? 'Industry' : undefined });
    };
    consumePendingRoute();
    const onOpenApp = (event: Event) => {
      if ((event as CustomEvent).detail?.appId === 'industry-knowledge') consumePendingRoute();
    };
    window.addEventListener('openApp', onOpenApp);
    return () => window.removeEventListener('openApp', onOpenApp);
  }, [navigate]);

  const selectedCategory = route.categoryId
    ? INDUSTRY_CATEGORIES.find((category) => category.id === route.categoryId) ?? null
    : null;
  const selectedGroup = INDUSTRY_GROUPS.find((group) => group.id === (route.groupId ?? selectedCategory?.groupId)) ?? null;
  const groupCategories = selectedGroup ? INDUSTRY_CATEGORIES.filter((category) => category.groupId === selectedGroup.id) : [];
  const selectedCompany = route.companyId
    ? selectedCategory?.companies?.find((company) => company.id === route.companyId) ?? null
    : null;

  const moduleHydrationTarget =
    selectedCategory && route.cardTitle
      ? { industryId: selectedCategory.id, cardTitle: route.cardTitle }
      : null;
  const moduleHydrationKey = moduleHydrationTarget
    ? industryModuleRouteKey(moduleHydrationTarget.industryId, moduleHydrationTarget.cardTitle)
    : null;
  const moduleHydrationRequired = moduleHydrationTarget
    ? needsIndustryModuleHydration(moduleHydrationTarget.industryId, moduleHydrationTarget.cardTitle)
    : false;
  const [moduleHydrationState, setModuleHydrationState] = useState<{
    key: string | null;
    status: 'idle' | 'loading' | 'ready' | 'error';
  }>({ key: null, status: 'idle' });
  const [moduleHydrationRetry, setModuleHydrationRetry] = useState(0);

  useEffect(() => {
    if (!moduleHydrationTarget || !moduleHydrationRequired) {
      setModuleHydrationState({ key: null, status: 'idle' });
      return;
    }
    const { industryId, cardTitle } = moduleHydrationTarget;
    const key = industryModuleRouteKey(industryId, cardTitle);
    setModuleHydrationState({ key, status: 'loading' });
    let cancelled = false;
    void hydrateIndustryModule(industryId, cardTitle)
      .then(() => {
        if (!cancelled) setModuleHydrationState({ key, status: 'ready' });
      })
      .catch((error) => {
        if (cancelled) return;
        setModuleHydrationState({ key, status: 'error' });
        trackStepError('industry-knowledge', route.lessonTitle ? 'learning_site' : 'choose_topic', error, { properties: { sector_id: industryId, topic_id: domainTrackingSlug(cardTitle) } });
      });
    return () => {
      cancelled = true;
    };
  }, [moduleHydrationTarget?.industryId, moduleHydrationTarget?.cardTitle, moduleHydrationRequired, moduleHydrationRetry]);

  const externalModuleHydrated =
    !moduleHydrationRequired ||
    (moduleHydrationState.key === moduleHydrationKey && moduleHydrationState.status === 'ready');
  const moduleHydrationFailed =
    moduleHydrationRequired &&
    moduleHydrationState.key === moduleHydrationKey &&
    moduleHydrationState.status === 'error';

  const selectedContentCard = (() => {
    if (!route.cardTitle || !selectedCategory) return null;
    const sectionKind = route.sectionKind ?? (selectedCompany ? 'Company' : 'Industry');
    const section = KNOWLEDGE_SECTIONS.find((item) => item.kind === sectionKind);
    const baseCard = section?.cards.find((item) => item.title === route.cardTitle);
    if (!section || !baseCard) return null;
    const card = resolveIndustryKnowledgeCard(baseCard, selectedCategory.id);
    const subCard = route.lessonTitle ? card.subCards?.find((item) => item.title === route.lessonTitle) : undefined;
    const contextName = selectedCompany
      ? `${selectedCompany.name} · ${section.title}`
      : `${selectedCategory.name} · ${section.title}`;
    return { card, section, contextName, subCard, industryId: selectedCategory.id };
  })();

  const dismissKnowledgeTransition = useCallback((id: number) => {
    setKnowledgeTransition((current) => current?.id === id ? null : current);
  }, []);

  useEffect(() => {
    const handlePopState = () => setRoute(readDomainKnowledgeRoute());
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  useEffect(() => {
    if (route.categoryId && !selectedCategory) {
      navigate({}, true);
      return;
    }
    if (selectedCategory && route.groupId !== selectedCategory.groupId) {
      navigate({ ...route, groupId: selectedCategory.groupId }, true);
      return;
    }
    if (route.groupId && !selectedGroup) navigate({}, true);
  }, [navigate, route, selectedCategory, selectedGroup]);

  useEffect(() => {
    const handleKnowledgeNavigation = (event: Event) => {
      const detail = (event as CustomEvent<KnowledgeNavigationState>).detail;
      if (!detail?.id || !detail.message) return;
      setKnowledgeTransition(detail);
    };
    window.addEventListener(KNOWLEDGE_NAVIGATION_EVENT, handleKnowledgeNavigation);
    return () => window.removeEventListener(KNOWLEDGE_NAVIGATION_EVENT, handleKnowledgeNavigation);
  }, []);

  useEffect(() => {
    if (openedRef.current) return;
    openedRef.current = true;
    try {
      void Promise.resolve(trackEvent('domain_opened', {
        event_role: 'open',
        feature_name: 'domain',
        source_kind: 'live',
      })).catch((error) => console.warn('[Domain Knowledge] analytics mirror failed:', error));
    } catch (error) {
      console.warn('[Domain Knowledge] analytics mirror failed:', error);
    }
  }, [trackEvent]);

  useEffect(() => {
    scrollContainerRef.current?.scrollTo({ top: 0, behavior: 'auto' });
  }, [route]);

  const trackingScreen: 'industry_site' | 'sector_site' | 'topic_site' | 'learning_path_site' | 'lesson' | null = basicEconomicsRoute
    ? null
    : selectedContentCard
      ? moduleHydrationFailed || !externalModuleHydrated
        ? null
        : selectedContentCard.subCard
          ? 'lesson'
          : selectedContentCard.card.subCards?.length ? 'learning_path_site' : null
      : selectedCompany
        ? null
        : selectedCategory && selectedGroup
          ? 'topic_site'
          : selectedGroup ? 'sector_site' : 'industry_site';
  const trackingIds = domainTrackingIdsFor({
    groupId: selectedGroup?.id,
    categoryId: selectedCategory?.id,
    companyId: selectedCompany?.id,
    cardTitle: selectedContentCard?.card.title,
    lessonTitle: selectedContentCard?.subCard?.title,
  });
  const trackingScreenKey = [trackingScreen, trackingIds.industry_slug, trackingIds.sector_id, trackingIds.company_id, trackingIds.topic_id, trackingIds.lesson_id].join('|');

  useEffect(() => {
    if (!trackingScreen) return;
    if (trackingScreen === 'lesson') {
      const move = takeDomainMove(domainLessonItemId(trackingIds));
      if (move) trackMove('industry-knowledge', move.moveType, { properties: { from_item_id: move.fromItemId, sector_id: trackingIds.sector_id, topic_id: trackingIds.topic_id, lesson_id: trackingIds.lesson_id } });
      return;
    }
    trackDomainTopicSubStep(trackingScreen, { properties: { industry_slug: trackingIds.industry_slug, sector_id: trackingIds.sector_id, topic_id: trackingIds.topic_id } });
  }, [trackingScreenKey]);

  const baseCategoryRoute = (): DomainKnowledgeRoute => ({
    groupId: selectedGroup?.id,
    categoryId: selectedCategory?.id,
    tab: route.tab ?? 'Industry',
  });

  const navigateToCard: NavigateToCard = (selection) => {
    navigate({
      ...baseCategoryRoute(),
      tab: selection.section.kind,
      companyId: selection.section.kind === 'Company' ? selectedCompany?.id : undefined,
      sectionKind: selection.section.kind,
      cardTitle: selection.card.title,
      lessonTitle: selection.subCard?.title,
    });
  };

  return (
    <div ref={scrollContainerRef} data-domain-scroll data-domain-mobile className="relative h-full max-h-[100dvh] overflow-x-hidden overflow-y-auto bg-white text-slate-900">
      <DomainMobileStyles />
      {knowledgeTransition && (
        <KnowledgeLoadingTransition key={knowledgeTransition.id} id={knowledgeTransition.id} message={knowledgeTransition.message} onDone={dismissKnowledgeTransition} />
      )}
      {learningModeAudit ? (
        <LearningModeAuditPanel load={loadLearningModeCatalog} onClose={closeLearningModeAudit} />
      ) : basicEconomicsRoute ? (
        <BasicEconomicsToolkits route={basicEconomicsRoute} onBack={() => setBasicEconomicsRoute(null)} />
      ) : selectedContentCard && moduleHydrationFailed ? (
        <main className="mx-auto flex min-h-[40vh] w-full max-w-3xl items-center justify-center px-4 py-12 sm:px-7" role="alert">
          <button
            type="button"
            onClick={() => setModuleHydrationRetry((attempt) => attempt + 1)}
            className="rounded-full bg-slate-900 px-5 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-slate-800"
          >
            Retry loading module
          </button>
        </main>
      ) : selectedContentCard && moduleHydrationRequired && !externalModuleHydrated ? (
        <main
          className="mx-auto flex min-h-[40vh] w-full max-w-3xl items-center justify-center px-4 py-12 sm:px-7"
          role="status"
          aria-busy="true"
          data-testid="industry-module-hydration"
        >
          <div className="h-2 w-40 animate-pulse rounded-full bg-slate-200" />
        </main>
      ) : selectedContentCard ? (
        <ContentDetailPage
          selection={selectedContentCard}
          onBack={() => navigate(selectedCompany ? { ...baseCategoryRoute(), tab: 'Company', companyId: selectedCompany.id } : baseCategoryRoute())}
          onOpenSubCard={(subCard) => navigate({ ...route, lessonTitle: subCard.title })}
          onOpenModule={(card) => navigate({ ...route, cardTitle: card.title, lessonTitle: undefined })}
          onCloseSubCard={() => navigate({ ...route, lessonTitle: undefined })}
          onOpenLesson={(cardTitle, lessonTitle) => navigate({ ...route, cardTitle, lessonTitle })}
        />
      ) : selectedCompany && selectedCategory ? (
        <CompanyDetailPage
          company={selectedCompany}
          industryName={selectedCategory.name}
          onBack={() => navigate({ ...baseCategoryRoute(), tab: 'Company' })}
          onOpenCard={navigateToCard}
        />
      ) : selectedCategory && selectedGroup ? (
        <CategoryDetail
          group={selectedGroup}
          category={selectedCategory}
          activeTab={route.tab ?? 'Industry'}
          onTabChange={(tab) => navigate({ groupId: selectedGroup.id, categoryId: selectedCategory.id, tab })}
          onBack={() => navigate({ groupId: selectedGroup.id })}
          onBackToAll={() => navigate({})}
          onSelectCompany={(company) => navigate({ groupId: selectedGroup.id, categoryId: selectedCategory.id, tab: 'Company', companyId: company.id })}
          navigateToCard={navigateToCard}
        />
      ) : selectedGroup ? (
        <SubcategoryList group={selectedGroup} categories={groupCategories} onSelect={(category) => navigate({ groupId: selectedGroup.id, categoryId: category.id, tab: 'Industry' })} onBack={() => navigate({})} />
      ) : (
        <CategoryList onSelect={(group) => navigate({ groupId: group.id })} onOpenBasicEconomics={() => setBasicEconomicsRoute({ nonce: Date.now() })} />
      )}
    </div>
  );
}

export default function IndustryKnowledge({ demo = false }: { demo?: boolean }) {
  const { trackEvent } = useSpaceRuntime();

  const handlePaywallBlocked = useCallback((reason: 'trial_ended') => {
    try {
      void Promise.resolve(trackEvent('domain_paywall_blocked', {
        reason,
        event_role: 'diagnostic',
        feature_name: 'domain',
        source_kind: 'live',
      })).catch((error) => console.warn('[Domain Knowledge] analytics mirror failed:', error));
    } catch (error) {
      console.warn('[Domain Knowledge] analytics mirror failed:', error);
    }
  }, [trackEvent]);

  if (demo) return <DomainKnowledgeScreen />;

  return (
    <PaywallGate appId="industry-knowledge" appName="Domain Knowledge" onBlocked={handlePaywallBlocked}>
      <DomainKnowledgeScreen />
    </PaywallGate>
  );
}
